class SquareCubeDataset(torch.utils.data.Dataset):
    def __init__(self, n):
        self.n = n
    def __len__(self):
        return self.n
    def __getitem__(self, idx):
        x = torch.tensor(idx, dtype=torch.float32)
        y = torch.tensor(idx**3, dtype=torch.float32)
        return x**2, y

dataset = SquareCubeDataset(10)
loader = torch.utils.data.DataLoader(dataset, batch_size=3, shuffle=False)
for batch_x, batch_y in loader:
    print(batch_x, batch_y)
# Output shows batches: [0,1,4] [0,1,8], then [9,16,25] [0,27,64], etc.
